const PROFILE_IDS = Object.freeze([
  "aegis-sage", "prism-warden", "rune-reaver", "scatterguard", "stormkite",
]);
const CLAIM_FAMILIES = Object.freeze({
  "aegis-sage": "reflection",
  "prism-warden": "pierce",
  "rune-reaver": "return",
  "scatterguard": "pellets",
  "stormkite": "chain",
});
const QUESTION_IDS = Object.freeze([
  "brassbolt", "briar-band", "copperskiff", "reedsting",
]);
const MANIFEST_KEYS = Object.freeze([
  "compositionOwnedIds", "counts", "excludedOccurrences", "identityRequirements",
  "occurrences", "profiles", "questionFixtures", "unresolvedDeliveryDependencies",
  "version",
]);
const PROFILE_KEYS = Object.freeze([
  "claims", "composition", "id", "identityRequirements", "occurrenceExports",
  "sharedHostIntegration", "sourceCard", "sourceIdentity",
]);
const CLAIM_KEYS = Object.freeze([
  "archetype", "claimFamily", "component", "delivery", "questions", "source",
]);
const SOURCE_CARD_KEYS = Object.freeze([
  "areaDamageRadiusMillitiles", "components", "cost", "count", "damage",
  "deployTimeTicks", "displayName", "firstHitTicks", "hitSpeedTicks", "hitpoints",
  "id", "kind", "movementMillitilesPerSecond", "rangeMillitiles", "rarity",
  "sightRangeMillitiles", "targetMode",
]);
const SOURCE_COMPONENT_KEYS = Object.freeze([
  "areaDamageRadiusMillitiles", "count", "damage", "deployTimeTicks", "displayName",
  "firstHitTicks", "hitSpeedTicks", "hitpoints", "id", "kind", "movementMillitilesPerSecond",
  "rangeMillitiles", "role", "sightRangeMillitiles", "targetMode",
]);
function canonical(value) {
  if (Array.isArray(value)) return "[" + value.map(canonical).join(",") + "]";
  if (value !== null && typeof value === "object") {
    return "{" + Object.keys(value).sort().map((key) =>
      JSON.stringify(key) + ":" + canonical(value[key])).join(",") + "}";
  }
  const encoded = JSON.stringify(value);
  if (encoded === undefined) throw new TypeError("projectile authority data cannot contain undefined");
  return encoded;
}

function freeze(value, seen = new WeakSet()) {
  if (value === null || typeof value !== "object" || seen.has(value)) return value;
  seen.add(value);
  for (const child of Object.values(value)) freeze(child, seen);
  return Object.freeze(value);
}

function exactKeys(value, expected, label) {
  if (value === null || typeof value !== "object" || Array.isArray(value) ||
      Object.getPrototypeOf(value) !== Object.prototype) {
    throw new TypeError(label + " must be a plain object");
  }
  const actual = Object.keys(value).sort();
  const keys = [...expected].sort();
  if (actual.length !== keys.length || actual.some((key, index) => key !== keys[index])) {
    throw new TypeError(label + " has an invalid field surface");
  }
  return value;
}

function exactArray(value, length, label) {
  if (!Array.isArray(value) || value.length !== length ||
      Object.getPrototypeOf(value) !== Array.prototype) {
    throw new TypeError(label + " is not the closed array");
  }
  return value;
}

function checkedSourceCard(value, label) {
  const card = exactKeys(value, SOURCE_CARD_KEYS, label);
  if (card.id === "" || typeof card.id !== "string" ||
      card.displayName === "" || typeof card.displayName !== "string" ||
      card.kind !== "unit" || typeof card.rarity !== "string" ||
      typeof card.targetMode !== "string" || !Array.isArray(card.components)) {
    throw new TypeError(label + " has invalid identity facts");
  }
  if (card.components.length > 16) {
    throw new TypeError(label + ".components exceeds its bound");
  }
  for (const [index, component] of card.components.entries()) {
    const checked = exactKeys(component, SOURCE_COMPONENT_KEYS, label + ".components[" + index + "]");
    if (checked.id === "" || typeof checked.id !== "string" ||
        checked.displayName === "" || typeof checked.displayName !== "string" ||
        checked.kind !== "unit" || typeof checked.role !== "string" ||
        typeof checked.targetMode !== "string") {
      throw new TypeError(label + ".components[" + index + "] has invalid identity facts");
    }
  }
  return card;
}

function checkedManifest() {
  let manifest;
  try {
    manifest = JSON.parse(CANONICAL_RECEIPT);
  } catch {
    throw new TypeError("closed projectile authority receipt is invalid");
  }
  if (canonical(manifest) !== CANONICAL_RECEIPT) {
    throw new TypeError("closed projectile authority receipt is not canonical");
  }
  exactKeys(manifest, MANIFEST_KEYS, "closed projectile authority receipt");
  if (manifest.version !== 1) {
    throw new TypeError("closed projectile authority version is unsupported");
  }
  if (canonical(manifest.profiles.map(({ id }) => id)) !== canonical(PROFILE_IDS)) {
    throw new TypeError("closed projectile authority profile roster diverges");
  }
  if (canonical(manifest.compositionOwnedIds) !== canonical(["aegis-sage"])) {
    throw new TypeError("closed projectile authority composition roster diverges");
  }
  exactArray(manifest.profiles, PROFILE_IDS.length, "closed projectile authority profiles");
  for (const [index, profile] of manifest.profiles.entries()) {
    const checked = exactKeys(profile, PROFILE_KEYS,
      "closed projectile authority profile[" + index + "]");
    const expectedFamily = CLAIM_FAMILIES[checked.id];
    if (expectedFamily === undefined) {
      throw new TypeError("closed projectile authority profile[" + index + "] has an unknown ID");
    }
    exactArray(checked.claims, 1,
      "closed projectile authority profile[" + index + "].claims");
    const claim = exactKeys(checked.claims[0], CLAIM_KEYS,
      "closed projectile authority profile[" + index + "].claim");
    if (claim.archetype !== checked.id || claim.claimFamily !== expectedFamily ||
        claim.component !== null || claim.delivery.classification !== "sourced" ||
        claim.delivery.delivery !== "projectile" ||
        checked.sourceIdentity.id !== checked.id ||
        canonical(checked.sourceCard) !== canonical(claim.source.record) ||
        checked.sharedHostIntegration.authority !== "LiveBattle" ||
        checked.sharedHostIntegration.status !== "pending-shared-host-integration") {
      throw new TypeError("closed projectile authority profile[" + index + "] diverges");
    }
    checkedSourceCard(checked.sourceCard,
      "closed projectile authority profile[" + index + "].sourceCard");
  }
  if (canonical(manifest.unresolvedDeliveryDependencies.map(({ id }) => id)) !==
      canonical(QUESTION_IDS)) {
    throw new TypeError("closed projectile authority QUESTION roster diverges");
  }
  for (const [index, dependency] of manifest.unresolvedDeliveryDependencies.entries()) {
    if (typeof dependency.id !== "string" || dependency.claimFamily === "" ||
        typeof dependency.claimFamily !== "string" ||
        dependency.questions?.delivery?.disposition !== "question" ||
        dependency.questions.delivery.authoritative !== false ||
        dependency.questions.delivery.key !== dependency.archetype + ".delivery") {
      throw new TypeError("closed projectile authority QUESTION[" + index + "] diverges");
    }
    checkedSourceCard(dependency.source.record,
      "closed projectile authority QUESTION[" + index + "].source.record");
  }
  return freeze(manifest);
}

const CANONICAL_MANIFEST = checkedManifest();

export const SESSION_TROOP_PROJECTILE_AUTHORITY_RECEIPT = CANONICAL_RECEIPT;

export function getSessionTroopProjectileAuthorityReceipt() {
  return CANONICAL_RECEIPT;
}

export function assertSessionTroopProjectileAuthorityReceipt(serialized) {
  if (typeof serialized !== "string") {
    throw new TypeError("session troop projectile authority receipt must be primitive text");
  }
  if (serialized !== CANONICAL_RECEIPT) {
    throw new TypeError("session troop projectile authority receipt is not the closed HTJP snapshot");
  }
  return true;
}
